// NOTE (mristin):
// Currently, Go does not support self-closing tags,
// see: https://github.com/golang/go/issues/21399.
// We apply the following hack to make the tags self-closing even if they are not.
// This is unsafe in general, but works OK for the limited set of test data that we are
// here dealing with.
//
// The code has been taken from: https://github.com/golang/go/issues/21399#issuecomment-1342730174

// NOTE (mristin):
// The opening tag, tag name plus an optional attribute list (*e.g.*,
// ``xmlns="..."`` on a root element), is captured in the first (and only)
// submatch group so that we do not lose any attributes when we force
// the tag to be self-closing below. The attribute list must not end with
// a slash, as we would otherwise match an already self-closing tag followed
// by the closing tag of its parent, *e.g.*, ``<someBytes /></something>``.
var emptyTagRe = regexp.MustCompile(`<(\w+(?:\s[^>]*[^/>])?)></\w+>`)

func forceSelfClosingTags(text string) string {
	b := []byte(text)
	emptyTagIdxs := emptyTagRe.FindAllSubmatchIndex(b, -1)

	if len(emptyTagIdxs) == 0 {
		return text
	}

	// NOTE (mristin):
	// The matches are walked in order, and the pieces of `b` between them are
	// copied over as they are. Mind that `nb` starts out empty and that `b` is
	// only ever *read*: an earlier version appended into `b[0:idx[0]]`, which
	// writes into `b`'s own backing array, so a document with more than one
	// empty tag came out garbled -- every turn of the loop then indexed into
	// a `b` which the previous turn had already overwritten.
	var nb []byte
	previous := 0

	for _, idx := range emptyTagIdxs {
		// Copy everything since the previous match, then the tag itself --
		// its name and its attributes -- as a self-closing one.
		nb = append(nb, b[previous:idx[0]]...)
		nb = append(nb, fmt.Sprintf("<%s/>", b[idx[2]:idx[3]])...)

		previous = idx[1]
	}

	// Finally, copy everything after the last match.
	nb = append(nb, b[previous:]...)

	return string(nb)
}

var whitespaceBetweenTagsRe = regexp.MustCompile(`>\s+<`)

// Remove all whitespace (including newlines, tabs, and spaces) between XML tags
// without parsing the XML.
func removeWhitespaceBetweenTags(text string) string {
	return whitespaceBetweenTagsRe.ReplaceAllString(text, "><")
}

var whitespaceBeforeAngleBracketsRe = regexp.MustCompile(`\s+>`)
var whitespaceBeforeSelfClosingRe = regexp.MustCompile(`\s+/>`)
var whitespaceAfterAngleBracketsRe = regexp.MustCompile(`<\s+`)

// Remove any whitespace before `>` and `/>` or after `<`
func removeWhitespaceWithinTags(text string) string {
	result := text
	result = whitespaceBeforeAngleBracketsRe.ReplaceAllString(result, ">")
	result = whitespaceBeforeSelfClosingRe.ReplaceAllString(result, "/>")
	result = whitespaceAfterAngleBracketsRe.ReplaceAllString(result, "<")
	return result
}

// Identify class containers, collection containers, and scalar content
// from each element's position in the model's XML structure.
func xmlTextContext(parent string, position int, name xml.Name) string {
	// Different tuple slots can have the same XML name.
	if strings.HasPrefix(parent, "tuple:") {
		parent += ":" + strconv.Itoa(position)
	}
	switch parent {
	case "class:Something":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "optionalText"}):
			return "text"
		case (xml.Name{Space: "https://dummy.com", Local: "parent"}):
			return "content:IParent"
		case (xml.Name{Space: "https://dummy.com", Local: "text"}):
			return "text"
		case (xml.Name{Space: "https://dummy.com", Local: "texts"}):
			return "content:ListOf_string"
		}
	case "content:IParent":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "childA"}):
			return "class:Child_a"
		case (xml.Name{Space: "https://dummy.com", Local: "childB"}):
			return "class:Child_b"
		}
	case "content:ListOf_string":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "v"}):
			return "text"
		}
	case "root":
		switch name {
		case (xml.Name{Space: "https://dummy.com", Local: "childA"}):
			return "class:Child_a"
		case (xml.Name{Space: "https://dummy.com", Local: "childB"}):
			return "class:Child_b"
		case (xml.Name{Space: "https://dummy.com", Local: "something"}):
			return "class:Something"
		}
	}
	return ""
}

// Keep numeric markup separate from the normalized XML so a change of number
// spelling can neither move a comment nor hide a change in its contents.
type xmlComparison struct {
	text, numericMarkup string
}

func normalizeXmlNumericContent(
	decoder *xml.Decoder, source, context string, numberIndex int, numericMarkup *strings.Builder,
) (string, error) {
	var content bytes.Buffer
	type mark struct {
		offset int
		xml    string
	}
	var marks []mark
	for {
		start := decoder.InputOffset()
		token, err := decoder.Token()
		if err != nil {
			return "", err
		}
		switch token := token.(type) {
		case xml.CharData:
			content.Write(token)
		case xml.Comment, xml.ProcInst:
			raw := source[start:decoder.InputOffset()]
			marks = append(marks, mark{content.Len(), raw})
		case xml.EndElement:
			// Reuse the SDK reader's lexical validation and double-precision conversion.
			// The sentinel element terminates the supplied character data for ReadText.
			number, _, err := xmlcommon.ReadTextAs_double(
				xml.NewDecoder(strings.NewReader("<end/>")), xml.CharData(content.Bytes()))
			if err != nil {
				return "", err
			}
			if context == "json:double" && (math.IsInf(number, 0) || math.IsNaN(number)) {
				return "", fmt.Errorf("expected a finite JSON number")
			}
			if len(marks) > 0 {
				// Count decoded numeric characters, excluding surrounding XML whitespace.
				// Leading and trailing marks stay at the boundaries even if the spelling changes length.
				text := content.Bytes()
				first := len(text) - len(bytes.TrimLeft(text, " \t\r\n"))
				end := len(bytes.TrimRight(text, " \t\r\n"))
				for _, m := range marks {
					var position string
					switch {
					case m.offset <= first:
						position = "start"
					case m.offset >= end:
						position = "end"
					default:
						position = strconv.Itoa(m.offset - first)
					}
					raw := strings.ReplaceAll(strings.ReplaceAll(m.xml, "\r\n", "\n"), "\r", "\n")
					fmt.Fprintf(numericMarkup, "number %d at %s: %q\n", numberIndex, position, raw)
				}
			}
			// FormatFloat preserves every representable value, including signed zero.
			canonical := strconv.FormatFloat(number, 'g', -1, 64)
			if math.IsInf(number, 1) {
				canonical = "INF"
			} else if math.IsInf(number, -1) {
				canonical = "-INF"
			}
			return canonical + source[start:decoder.InputOffset()], nil
		default:
			return "", fmt.Errorf("expected numeric text, got %T", token)
		}
	}
}

// Normalize character escaping and numeric spelling while retaining the markup.
// Copying tags verbatim avoids changing namespace declarations or prefixes.
func normalizeXmlTextEscaping(text string) (xmlComparison, error) {
	decoder := xml.NewDecoder(strings.NewReader(text))
	var result bytes.Buffer
	var numericMarkup strings.Builder
	numberIndex := 0
	type frame struct {
		context  string
		children int
	}
	stack := []frame{{context: "root"}}
	for {
		start := decoder.InputOffset()
		token, err := decoder.Token()
		if err == io.EOF {
			return xmlComparison{result.String(), numericMarkup.String()}, nil
		}
		if err != nil {
			return xmlComparison{}, err
		}
		if element, ok := token.(xml.StartElement); ok {
			parent := &stack[len(stack)-1]
			parent.children++
			context := xmlTextContext(parent.context, parent.children, element.Name)
			if context == "double" || context == "json:double" {
				result.WriteString(text[start:decoder.InputOffset()])
				numberIndex++
				normalized, err := normalizeXmlNumericContent(decoder, text, context, numberIndex, &numericMarkup)
				if err != nil {
					return xmlComparison{}, err
				}
				result.WriteString(normalized)
				continue
			}
			stack = append(stack, frame{context: context})
		}
		if data, ok := token.(xml.CharData); ok {
			// Normalize strings consistently, even if they consist only of whitespace.
			// Keep container indentation available to the existing cleanup.
			if stack[len(stack)-1].context != "text" && strings.Trim(string(data), " \t\r\n") == "" {
				result.WriteString(text[start:decoder.InputOffset()])
			} else {
				var escaped bytes.Buffer
				if err := xml.EscapeText(&escaped, data); err != nil {
					return xmlComparison{}, err
				}
				if stack[len(stack)-1].context == "text" {
					// Protect spaces as well as tabs and line breaks from the regex cleanup.
					result.WriteString(strings.ReplaceAll(escaped.String(), " ", "&#32;"))
				} else {
					result.Write(escaped.Bytes())
				}
			}
		} else {
			result.WriteString(text[start:decoder.InputOffset()])
		}
		if _, ok := token.(xml.EndElement); ok {
			stack = stack[:len(stack)-1]
		}
	}
}

func TestWritePositiveInfinity(t *testing.T) {
	var output strings.Builder
	encoder := xml.NewEncoder(&output)
	if err := xmlcommon.WriteAsText_double(encoder, math.Inf(1)); err != nil {
		t.Fatal(err)
	}
	if err := encoder.Flush(); err != nil {
		t.Fatal(err)
	}
	// XSD 1.0 requires INF even though the reader also accepts +INF.
	if got := output.String(); got != "INF" {
		t.Fatalf("Expected positive infinity as %q, got %q", "INF", got)
	}
}

func TestNormalizeXmlTextEscaping(t *testing.T) {
	cases := []struct {
		name  string
		input string
		want  string
	}{
		{"quotes", `<v>"hello"</v>`, `<v>&#34;hello&#34;</v>`},
		{"quote_references", `<v>&quot;hello&#x22;</v>`, `<v>&#34;hello&#34;</v>`},
		{"apostrophes", `<v>'hello'</v>`, `<v>&#39;hello&#39;</v>`},
		{"tabs", "<v>a\tb</v>", `<v>a&#x9;b</v>`},
		{"tab_reference", `<v>a&#9;b</v>`, `<v>a&#x9;b</v>`},
		{"double_escaping", `<v>&amp;#34;</v>`, `<v>&amp;#34;</v>`},
		{"text_is_not_markup", `<v>&#60;x/&#62;</v>`, `<v>&lt;x/&gt;</v>`},
		{"string_spaces", `<v> hello </v>`, `<v> hello </v>`},
		{"markup", `<p:v xmlns:p='urn:test' a='"'/>`, `<p:v xmlns:p='urn:test' a='"'/>`},
		{"numbers", `<v>1e2</v>`, `<v>1e2</v>`},
		{"indentation", "<r>\n\t<v/>\n</r>", "<r>\n\t<v/>\n</r>"},
		{"whitespace_reference", `<v>&#x9;</v>`, `<v>&#x9;</v>`},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, err := normalizeXmlTextEscaping(c.input)
			if err != nil {
				t.Fatal(err)
			}
			if got.text != c.want {
				t.Fatalf("Expected %q, got %q", c.want, got)
			}
		})
	}
}

const xmlComparisonMarker = "GITHUB_COM_DUMMY_WORKS_DUMMY_XML_COMPARISON_LITERAL"

func canonicalizeXmlForComparison(text string) (xmlComparison, error) {
	text = strings.TrimSpace(text)
	// Escape text before applying the legacy markup cleanup, so a literal
	// '>' in a value can not make the cleanup remove a preceding space.
	comparison, err := normalizeXmlTextEscaping(text)
	if err != nil {
		return xmlComparison{}, err
	}
	text = comparison.text
	// Protect literal content while the legacy regexes clean up markup.
	// Check after simulating carriage-return removal so cleanup cannot turn
	// existing XML text into a placeholder that gets replaced on restoration.
	markerPrefix := xmlComparisonMarker
	withoutCR := strings.ReplaceAll(text, "\r", "")
	for strings.Contains(withoutCR, markerPrefix) {
		markerPrefix += "X"
	}
	// Collect placeholder/original pairs for a single-pass restoration.
	var replacements []string
	protectLiteral := func(original string, asMarkup bool) string {
		marker := fmt.Sprintf("%s_%d_", markerPrefix, len(replacements)/2)
		if asMarkup {
			marker = "<?" + marker + "?>"
		}
		// XML 1.0 section 2.11 normalizes literal line endings before parsing.
		original = strings.ReplaceAll(strings.ReplaceAll(original, "\r\n", "\n"), "\r", "\n")
		replacements = append(replacements, marker, original)
		return marker
	}
	var protected bytes.Buffer
	decoder := xml.NewDecoder(strings.NewReader(text))
	for {
		start := decoder.InputOffset()
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return xmlComparison{}, err
		}
		original := text[start:decoder.InputOffset()]
		switch token.(type) {
		case xml.Comment, xml.ProcInst:
			protected.WriteString(protectLiteral(original, true))
		case xml.StartElement:
			// Quoted attribute values can contain '>' and the other quote character.
			// Keep the original quotes and protect only the contents between them.
			cursor := 0
			for i := 0; i < len(original); i++ {
				quote := original[i]
				if quote != '\'' && quote != '"' {
					continue
				}
				end := i + 1
				for end < len(original) && original[end] != quote {
					end++
				}
				if end == len(original) {
					return xmlComparison{}, fmt.Errorf("unterminated XML attribute value")
				}
				protected.WriteString(original[cursor : i+1])
				protected.WriteString(protectLiteral(original[i+1:end], false))
				protected.WriteByte(quote)
				cursor = end + 1
				i = end
			}
			protected.WriteString(original[cursor:])
		default:
			protected.WriteString(original)
		}
	}
	text = protected.String()
	text = strings.ReplaceAll(text, "\r", "")
	text = removeWhitespaceBetweenTags(text)
	text = forceSelfClosingTags(text)
	text = removeWhitespaceWithinTags(text)
	if len(replacements) > 0 {
		text = strings.NewReplacer(replacements...).Replace(text)
	}
	comparison.text = text
	return comparison, nil
}

func TestXmlComparisonPreservesText(t *testing.T) {
	for _, c := range []struct {
		name     string
		expected string
		actual   string
		equal    bool
	}{
		{"equivalent_escaping", `<v>x ></v>`, `<v>x &gt;</v>`, true},
		{"lost_space", `<v>x ></v>`, `<v>x&gt;</v>`, false},
		{"numeric_reference", `<v>x ></v>`, `<v>x &#62;</v>`, true},
		{"extra_space", `<v>x ></v>`, `<v>x  &gt;</v>`, false},
		{"tab_vs_newline", `<v>&#x9;</v>`, `<v>&#xA;</v>`, false},
		{"tab_vs_space", `<v>&#x9;</v>`, `<v>&#32;</v>`, false},
		{"lost_tab", `<v>&#x9;</v>`, `<v></v>`, false},
		{"space_vs_literal_tab", `<v>&#32;</v>`, "<v>\t</v>", false},
		{"attribute_space", `<v label="a >b"/>`, `<v label="a>b"/>`, false},
		{"attribute_single_quote", `<v label='a >b'/>`, `<v label='a>b'/>`, false},
		{"attribute_mixed_quotes", `<v label='a " >b'/>`, `<v label='a ">b'/>`, false},
		{"attribute_empty_element", `<v label="a >b"></v>`, `<v label="a >b"/>`, true},
		{"attribute_tag_spacing", `<v label="a >b" />`, `<v label="a >b"/>`, true},
		{"attribute_crlf", "<v label=\"a\r\nb\"/>", "<v label=\"a\nb\"/>", true},
		{"attribute_cr", "<v label=\"a\rb\"/>", "<v label=\"ab\"/>", false},
		{
			"attribute_many_literals",
			`<v a0="0" a1="1" a2="2" a3="3" a4="4" a5="5"` +
				` a6="6" a7="7" a8="8" a9="9" a10="10"/>`,
			`<v a0="0" a1="1" a2="2" a3="3" a4="4" a5="5"` +
				` a6="6" a7="7" a8="8" a9="9" a10="changed"/>`,
			false,
		},
		{
			"namespace_changed",
			`<p:v xmlns:p="urn:a" label="a >b"/>`,
			`<p:v xmlns:p="urn:b" label="a >b"/>`, false,
		},
		{"comment_markup", `<v><!--<c></c>--></v>`, `<v><!--<c/>--></v>`, false},
		{"comment_space", `<v><!--a >b--></v>`, `<v><!--a>b--></v>`, false},
		{"comment_crlf", "<v><!--a\r\nb--></v>", "<v><!--a\nb--></v>", true},
		{"comment_cr_as_lf", "<v><!--a\rb--></v>", "<v><!--a\nb--></v>", true},
		{"comment_cr", "<v><!--a\rb--></v>", `<v><!--ab--></v>`, false},
		{"instruction_data", `<v><?p x > y?></v>`, `<v><?p x> y?></v>`, false},
		{"instruction_markup", `<v><?p <a></a>?></v>`, `<v><?p <a/>?></v>`, false},
		{"instruction_cr", "<v><?p x\ry?></v>", `<v><?p xy?></v>`, false},
		{"instruction_cr_as_lf", "<v><?p x\ry?></v>", "<v><?p x\ny?></v>", true},
		{"instruction_crlf_as_lf", "<v><?p x\r\ny?></v>", "<v><?p x\ny?></v>", true},
		{"instruction_indentation", "<v>\n<?p x > y?>\n</v>", `<v><?p x > y?></v>`, true},
		{
			"instruction_marker",
			"<v><!--<?" + xmlComparisonMarker + "_0_?>--><?p x?></v>",
			"<v><!--<?p x?>--><?p x?></v>",
			false,
		},
		{
			"attribute_marker",
			"<v a=\"" + xmlComparisonMarker + "_0_\" b=\"other\"/>",
			"<v a=\"other\" b=\"other\"/>",
			false,
		},
	} {
		t.Run(c.name, func(t *testing.T) {
			expected, err := canonicalizeXmlForComparison(c.expected)
			if err != nil {
				t.Fatal(err)
			}
			actual, err := canonicalizeXmlForComparison(c.actual)
			if err != nil {
				t.Fatal(err)
			}
			if (expected == actual) != c.equal {
				t.Fatalf("Unexpected comparison of %q and %q", expected, actual)
			}
		})
	}
}

// Assert that the serialization `other`, as XML document, equals the original
//
//	XML document `that` read from the `source`.
func assertSerializationEqualsDeserialization(
	t *testing.T,
	that string,
	other string,
	source string,
) (ok bool) {
	ok = true

	// NOTE (mristin):
	// The following hack is SUPER ugly and unsafe! However, it works. Given Go's
	// limited support for XML, we gave up on a safer approach :(. We tested
	// the following approaches before applying this hack:
	//  * A round-trip over `encoding/xml`. Failed due to
	//    https://github.com/golang/go/issues/13400.
	//  * Using `aqwari.net/xml/xmltree`. Failed as the special characters in the
	//    element content still has not been de-escaped or consistently escaped in
	//    a round trip.

	canonicalThat, err := canonicalizeXmlForComparison(that)
	if err != nil {
		t.Fatalf("Failed to normalize original XML from %s: %s", source, err)
		return false
	}
	canonicalOther, err := canonicalizeXmlForComparison(other)
	if err != nil {
		t.Fatalf("Failed to normalize serialized XML from %s: %s", source, err)
		return false
	}

	if canonicalThat.numericMarkup != canonicalOther.numericMarkup {
		t.Fatalf("Numeric XML markup differs in %s:\nORIGINAL:\n%sSERIALIZED:\n%s",
			source, canonicalThat.numericMarkup, canonicalOther.numericMarkup)
	}
	thatLines := strings.Split(canonicalThat.text, "\n")
	otherLines := strings.Split(canonicalOther.text, "\n")

	if canonicalThat.text != canonicalOther.text {
		b := new(strings.Builder)
		minLines := len(thatLines)
		if minLines > len(otherLines) {
			minLines = len(otherLines)
		}
		for i := 0; i < minLines; i++ {
			if thatLines[i] == otherLines[i] {
				b.WriteString(fmt.Sprintf("           %s\n", thatLines[i]))
			} else {
				b.WriteString(fmt.Sprintf("ORIGINAL   %s\n", thatLines[i]))
				b.WriteString(fmt.Sprintf("SERIALIZED %s\n", otherLines[i]))
				break
			}
		}

		ok = false
		t.Fatalf(
			"The canonicalized XML serialization of the de-serialized instance "+
				"from %s does not equal the canonicalized original XML document:\n"+
				"%s",
			source, b.String(),
		)
		return
	}

	return
}

// Assert that there is a de-serialization error.
//
// If [ourtesting.RecordMode] is set, the de-serialization error is re-recorded
// to `expectedPth`. Otherwise, the error is compared against the golden file
// `expectedPth`.
func assertIsDeserializationErrorAndEqualsExpectedOrRecord(
	t *testing.T,
	err error,
	source string,
	expectedPth string,
) (ok bool) {
	ok = true

	if err == nil {
		ok = false
		t.Fatalf("De-serialization error expected from %s, but got none", source)
		return
	}

	deseriaErr, is := err.(*ourxmlization.DeserializationError)
	if !is {
		ok = false
		t.Fatalf(
			"Expected a de-serialization error, "+
				"but got an error of type %T from %s: %v",
			err, source, err,
		)
		return
	}

	// Add a new line for POSIX systems.
	got := deseriaErr.Error() + "\n"

	if ourtesting.RecordMode {
		parent := filepath.Dir(expectedPth)
		err := os.MkdirAll(parent, os.ModePerm)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to create the directory %s: %s", parent, err.Error(),
				),
			)
		}

		err = os.WriteFile(expectedPth, []byte(got), 0644)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to write to the file %s: %s", expectedPth, err.Error(),
				),
			)
		}
	} else {
		_, err := os.Stat(expectedPth)
		if err != nil {
			ok = false
			t.Fatalf(
				"Failed to stat the file %s: %s; if the file does not exist, "+
					"you probably want to record the test data by "+
					"setting the environment variable %s",
				expectedPth, err.Error(), ourtesting.RecordModeEnvironmentVariableName,
			)
			return
		}

		bb, err := os.ReadFile(expectedPth)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to read from file %s: %s", expectedPth, err.Error(),
				),
			)
		}

		expected := string(bb)

		// NOTE (mristin):
		// Git automatically strips and adds `\r`, so we have to remove it here
		// to obtain a canonical text.
		expected = strings.Replace(expected, "\r", "", -1)

		if expected != got {
			ok = false
			t.Fatalf(
				"What we got differs from the expected in %s. "+
					"We got:\n%s\nWe expected:\n%s",
				expectedPth, got, expected,
			)
			return
		}
	}

	return
}

